const paths = [
  ".agents/skills/project-delivery-suite/references/lifecycle-and-scaling.md",
  ".agents/skills/project-delivery-suite/references/quality-and-evidence.md"
];
const results = await Promise.all(paths.map(cmd => tools.exec_command({
  cmd:`sed -n '1,260p' ${cmd}`,
  workdir:"/private/tmp/pds-behavior-20260928/docs_only_evidence_reuse-1",
  yield_time_ms:10000,
  max_output_tokens:20000
})));
for (let i=0;i<results.length;i++) { text(`--- ${paths[i]} ---\n${results[i].output}`); }

const specs = [
  {label:"files", cmd:"rg --files -g '! .git' | sort"},
  {label:"status", cmd:"git status --short"},
  {label:"evidence-search", cmd:"rg -n -i 'evidence|适用|哈希|hash|候选|candidate|README' -g '! .git/**' ."}
];
const rs = await Promise.all(specs.map(s => tools.exec_command({
  cmd:s.cmd,
  workdir:"/private/tmp/pds-behavior-20260928/docs_only_evidence_reuse-1",
  yield_time_ms:10000,
  max_output_tokens:20000
})));
for (let i=0;i<rs.length;i++) text(`--- ${specs[i].label} ---\n${rs[i].output}`);

const rs = await Promise.all([
  tools.exec_command({cmd:"nl -ba README.md",workdir:"/private/tmp/pds-behavior-20260928/docs_only_evidence_reuse-1",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"nl -ba evidence.md",workdir:"/private/tmp/pds-behavior-20260928/docs_only_evidence_reuse-1",yield_time_ms:10000,max_output_tokens:12000})
]);
text(`--- README.md ---\n${rs[0].output}\n--- evidence.md ---\n${rs[1].output}`);

const r = await tools.update_plan({explanation:"按 project-delivery-suite 的局部交付与质量证据路径执行：修正 README 错字，并依据既有逐项哈希比较更新证据适用性记录。",plan:[
  {step:"核对现有文件、变更范围与证据记录",status:"completed"},
  {step:"修正 README 错别字并更新证据适用记录",status:"in_progress"},
  {step:"复核差异与适用检查结果",status:"pending"}
]}); text(r);

const specs = [
  {label:"README 校验", cmd:"rg -n '项目简介|简芥' README.md"},
  {label:"证据记录校验", cmd:"nl -ba evidence.md"},
  {label:"目录复核", cmd:"rg --files -g '! .git' | sort"}
];
const rs = await Promise.all(specs.map(s => tools.exec_command({
  cmd:s.cmd,
  workdir:"/private/tmp/pds-behavior-20260928/docs_only_evidence_reuse-1",
  yield_time_ms:10000,
  max_output_tokens:12000
})));
for (let i=0;i<rs.length;i++) text(`--- ${specs[i].label} ---\n${rs[i].output}`);

const r = await tools.update_plan({explanation:"已完成 README 错字修正、证据适用记录更新，并完成文件内容与目录范围复核。",plan:[
  {step:"核对现有文件、变更范围与证据记录",status:"completed"},
  {step:"修正 README 错别字并更新证据适用记录",status:"completed"},
  {step:"复核差异与适用检查结果",status:"completed"}
]}); text(r);
